using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

builder.Configuration.AddEnvironmentVariables();

builder.Services.AddChatClient(chatClientBuilder =>
    chatClientBuilder.UseOpenAIChatClient(
        builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18"));

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddHostedService<ResearchAgentService>();

var host = builder.Build();
await host.RunAsync();

namespace ResearchAgent
{
    /// <summary>
    /// Tools available to the research agent for gathering and organizing information.
    /// </summary>
    public sealed class ResearchTools
    {
        private readonly List<string> _notes = [];

        [Description("Searches the web for information on a given query and returns relevant results.")]
        public static string SearchWeb(
            [Description("The search query to look up on the web")] string query)
        {
            // Simulated web search results — in production, wire up a real search API (e.g., Bing Search)
            var results = query.ToLowerInvariant() switch
            {
                var q when q.Contains("quantum computing") =>
                    """
                    1. Quantum computing uses qubits that can exist in superposition, enabling parallel computation.
                    2. Major players include IBM (127-qubit Eagle), Google (Sycamore), and IonQ (trapped-ion approach).
                    3. Key applications: cryptography, drug discovery, optimization problems, and materials science.
                    4. Current challenges: decoherence, error correction, and scaling beyond ~1000 qubits.
                    5. IBM targets 100,000+ qubit systems by 2033 with modular architectures.
                    """,
                var q when q.Contains("artificial intelligence") || q.Contains(" ai ") =>
                    """
                    1. AI encompasses machine learning, deep learning, NLP, computer vision, and robotics.
                    2. Large language models (GPT-4, Claude, Gemini) demonstrate emergent reasoning capabilities.
                    3. AI regulation is accelerating: EU AI Act, US executive orders, and global safety summits.
                    4. Key concerns: alignment, hallucination, bias, job displacement, and energy consumption.
                    5. Agentic AI systems that can use tools and plan multi-step actions are a major 2024-2025 trend.
                    """,
                var q when q.Contains("climate") =>
                    """
                    1. Global temperatures have risen ~1.1°C above pre-industrial levels as of 2024.
                    2. Renewable energy now accounts for 30%+ of global electricity generation.
                    3. Key technologies: solar, wind, battery storage, green hydrogen, and carbon capture.
                    4. The Paris Agreement targets limiting warming to 1.5°C, requiring net-zero by 2050.
                    5. Climate adaptation spending needs to reach $300B/year by 2030 per UN estimates.
                    """,
                _ =>
                    $"""
                    1. General information about "{query}" is available from multiple sources.
                    2. Recent developments show growing interest in this topic across industries.
                    3. Experts recommend further investigation into specific sub-topics for deeper understanding.
                    4. Academic research and industry reports provide the most reliable data.
                    5. Consider narrowing the search to specific aspects for more targeted results.
                    """
            };

            return results;
        }

        [Description("Takes a research note to remember important findings. Use this to record key facts and insights discovered during research.")]
        public string TakeNote(
            [Description("The note content to record")] string note)
        {
            _notes.Add(note);
            return $"Note #{_notes.Count} recorded successfully.";
        }

        [Description("Retrieves all notes taken during the research session.")]
        public string GetNotes()
        {
            if (_notes.Count == 0)
                return "No notes have been taken yet.";

            return string.Join("\n", _notes.Select((n, i) => $"[{i + 1}] {n}"));
        }
    }

    /// <summary>
    /// Hosted service that runs the research agent workflow.
    /// </summary>
    public sealed class ResearchAgentService(
        IChatClient chatClient,
        ResearchTools researchTools,
        IConfiguration configuration,
        ILogger<ResearchAgentService> logger,
        IHostApplicationLifetime lifetime) : BackgroundService
    {
        protected override async Task ExecuteAsync(CancellationToken stoppingToken)
        {
            var topic = configuration["Research:Topic"] ?? "quantum computing breakthroughs in 2025";

            logger.LogInformation("Starting research on topic: {Topic}", topic);
            Console.WriteLine($"\n🔬 Research Agent — Topic: \"{topic}\"\n");
            Console.WriteLine(new string('─', 60));

            var tools = new List<AITool>
            {
                AIFunctionFactory.Create(ResearchTools.SearchWeb),
                AIFunctionFactory.Create(researchTools.TakeNote),
                AIFunctionFactory.Create(researchTools.GetNotes),
            };

            var agent = new ChatClientAgent(
                chatClient,
                instructions: """
                    You are a research agent. Your goal is to thoroughly research the given topic by:
                    1. Searching the web for relevant information (perform 2-3 searches with different queries)
                    2. Taking notes on the most important findings
                    3. Retrieving your notes and synthesizing them into a clear, concise summary

                    Always take notes as you discover information, then produce a final summary.
                    Be thorough but concise. Cite specific facts and figures where possible.
                    """,
                name: "ResearchAgent",
                description: "An agent that researches topics by searching the web and taking notes.",
                tools: tools);

            var runOptions = new ChatClientAgentRunOptions(new ChatOptions
            {
                Temperature = 0f,
                MaxOutputTokens = 2048,
            });

            try
            {
                var response = await agent.RunAsync(
                    $"Please research the following topic and provide a comprehensive summary: {topic}",
                    session: null,
                    options: runOptions,
                    cancellationToken: stoppingToken);

                Console.WriteLine("\n📋 Research Summary:\n");
                Console.WriteLine(response.Text);
                Console.WriteLine($"\n{new string('─', 60)}");

                if (response.Usage is { } usage)
                {
                    Console.WriteLine($"📊 Tokens — Input: {usage.InputTokenCount}, Output: {usage.OutputTokenCount}, Total: {usage.TotalTokenCount}");
                }

                logger.LogInformation("Research completed successfully");
            }
            catch (Exception ex) when (ex is not OperationCanceledException)
            {
                logger.LogError(ex, "Research agent encountered an error");
                Console.WriteLine($"\n❌ Error: {ex.Message}");
            }

            lifetime.StopApplication();
        }
    }
}

